INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('3/4 Sit-Up', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol and secure vos pieds. vos jambes should be bent at the genoux. 2. Place vos mains behind or to the side of your head. You will begin with votre dos on the ground. Position de depart. 3. Flex your hips and spine to raise your torse toward your genoux. 4. At the top of the contraction your torse should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/3_4_Sit-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('90/90 Hamstring', 'Ischio-jambiers', 'Poids de corps', '1. Allongez-vous au sol, with one leg extended straight out. 2. With the other leg, bend the hip and genoux to 90 degrees. You may brace your leg with vos mains if necessary. Position de depart. 3. Extend your leg straight into the air, pausing briefly at the top. Return the leg to the position de depart. 4. Repetez for 10-20 repetitions, and then switch to the other leg.', 'Muscles secondaires : Mollets. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ab Crunch Machine', 'Abdominaux', 'Machine', '1. Select a light resistance and sit down on the ab machine placing vos pieds under the pads provided and grabbing the top handles. vos bras should be bent at a 90 degree angle as you rest the triceps on the pads provided. Position de depart. 2. At the same time, begin to lift the legs up as you crunch your upper torse. Expirez as you perform this movement. Conseil : Be sure to use a slow and controlled motion. Concentrate on using your abdominaux to move the poids while relaxing vos jambes and feet. 3. Apres une pause, Lentement, Revenez en position de depart as you Inspirez. 4. Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ab Roller', 'Abdominaux', 'Autre', '1. Hold the Ab Roller with both hands and kneel on le sol. 2. Now place the ab roller on le sol in front of you so that you are on all vos mains and genoux (as in a kneeling push up position). Position de depart. 3. Lentement, roll the ab roller straight forward, stretching votre corps into a straight position. Conseil : Go down as far as you can without touching le sol with votre corps. Inspirez during this portion of le mouvement. 4. Apres une pause, at the stretched position, start pulling yourself back to the position de depart as you Expirez. Conseil : Go Lentement, and keep your abdominaux tight en permanence.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Adductor', 'Adducteurs', 'Foam roller', '1. Lie face down with one leg on a foam roll. 2. Rotate the leg so that the foam roll contacts against your inner cuisses. Shift as much poids onto the foam roll as can be tolerated. 3. While trying to relax the muscles if the inner cuisses, roll over the foam between your hip and genoux, holding points of tension for 10-30 seconds. Repetez with the other leg.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Adductor/Groin', 'Adducteurs', 'Autre', '1. Allongez-vous au sol with vos pieds raised towards the ceiling. 2. Have your partner hold vos pieds or ankles. Abduct vos jambes as far as you can. Position de depart. 3. Attempt to squeeze vos jambes together for 10 or more seconds, while your partner prevents you from doing so. 4. Now, relax the muscles in vos jambes as your partner pushes vos pieds apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Advanced Kettlebell Windmill', 'Abdominaux', 'Kettlebell', '1. Clean and press a kettlebells overhead with one arm. 2. Keeping the kettlebells locked out en permanence, push your butt out in the direction of the locked out kettlebells. Keep the non-working arm behind votre dos and turn vos pieds out at a forty-five degree angle from the arm with the kettlebells. 3. Lower yourself as far as possible. 4. Pause for a second and reverse the motion back to the position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Advanced_Kettlebell_Windmill/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Air Bike', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with your lower back pressed to the ground. For this exercise, you will need to put vos mains beside your head. Be careful however to not strain with the neck as you perform it. Now lift your epaules into the crunch position. 2. Bring genoux up to where they are perpendicular to le sol, with your lower legs parallel to le sol. Position de depart. 3. Now simultaneously, Lentement, go through a cycle pedal motion kicking forward with the right leg and bringing in the genoux of the left leg. Bring your right coudes close to your left genoux by crunching to the side, as you Expirez. 4. Go back to the initial position as you Inspirez. 5. Crunch to the opposite side as you cycle vos jambes and bring closer your left coudes to your right genoux and exhale. 6. Continue alternating in this manner until all of the recommended repetitions for each side have been completed.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('All Fours Quad Stretch', 'Quadriceps', 'Poids de corps', '1. Start off on vos mains and genoux, then lift your leg off le sol and hold the foot with your hand. 2. Use your hand to hold the foot or ankle, keeping the genoux fully flexed, stretching the quadriceps and hip flexors. 3. Focus on extending your hips, thrusting them towards le sol. Hold for 10-20 seconds and then switch sides.', 'Muscles secondaires : Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Hammer Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec your torse upright and a halteres in each hand being held bras tendus. The coudes should be close to the torse. 2. The palms of the hands should be facing your torse. Position de depart. 3. While holding the upper arm stationary, curl the right poids forward while contracting the biceps as you Expirez. Continue le mouvement until your biceps is entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. Conseil : Only the forearms should move. 4. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 5. Repetez le mouvement with the left hand. This equals one repetition. 6. Continue alternating in this manner for the recommended amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Heel Touchers', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with the genoux bent and the feet on le sol around 18-24 inches apart. vos bras should be extended by your side. Position de depart. 2. Crunch over your torse forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. 3. Now go back Lentement, to the position de depart en inspirant. 4. Now crunch over your torse forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the position de depart en inspirant. Now that both heels have been touched, that is considered 1 repetition. 5. Continue alternating sides in this manner until all prescribed repetitions are done.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Heel_Touchers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Incline Dumbbell Curl', 'Biceps', 'Haltères', '1. Asseyez-vous sur un banc with a halteres in each hand being held bras tendus. Conseil : Keep the coudes close to the torse.Position de depart. 2. While holding the upper arm stationary, curl the right poids forward while contracting the biceps as you Expirez. As you do so, rotate the hand so that the palm is facing up. Continue le mouvement until your biceps is entierement contracte and the halteres are at epaules level. Maintenez 1 seconde as you squeeze the biceps. Conseil : Only the forearms should move. 3. Lentement, begin to bring the halteres back to position de depart as your Inspirez. 4. Repetez le mouvement with the left hand. This equals one repetition. 5. Continue alternating in this manner for the recommended amount of repetitions.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternate Leg Diagonal Bound', 'Quadriceps', 'Autre', '1. Assume a comfortable stance with one foot slightly in front of the other. 2. Begin by pushing off with the front leg, driving the opposite genoux forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. 3. It may help to use a line on the ground to guage distance from side to side. 4. Repetez the sequence with the other leg.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Cable Shoulder Press', 'Épaules', 'Poulie', '1. Move the cables to the bottom of the tower and select an appropriate poids. 2. Grasp the cables and hold them at epaules height, palms facing forward. Position de depart. 3. Keeping your head and poitrine up, extend through the coudes to press one side directly over head. 4. After pausing at the top, Revenez en position de depart and Repetez de l autre cote.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Cable_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Deltoid Raise', 'Épaules', 'Haltères', '1. In a standing position, hold a pair of halteres at your side. 2. Keeping your coudes slightly bent, raise the poids directly in front of you to epaules height, avoiding any swinging or cheating. 3. Return the poids to your side. 4. On the next repetition, raise the poids laterally, raising them out to your side to about epaules height. 5. Return the poids to the position de depart and continue alternating to the front and side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Floor Press', 'Pectoraux', 'Kettlebell', '1. Allongez-vous au sol with two kettlebells next to your epaules. 2. Position one in place on your poitrine and then the other, gripping the kettlebells on the handle with the palms facing forward. 3. Extend both arms, so that the kettlebells are being held above your poitrine. Lower one kettlebells, bringing it to your poitrine and turn the poignets in the direction of the locked out kettlebells. 4. Raise the kettlebells and Repetez de l autre cote.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Floor_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Hang Clean', 'Ischio-jambiers', 'Kettlebell', '1. Place two kettlebells between vos pieds. To get in the position de depart, push your butt back and look straight ahead. 2. Clean one kettlebells to your epaules and hold on to the other kettlebells in a hanging position. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. 3. Lower the cleaned kettlebells to a hanging position and clean the alternate kettlebells. Repetez.', 'Muscles secondaires : Biceps, Mollets, Avant-bras, Fessiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Kettlebell Press', 'Épaules', 'Kettlebell', '1. Clean two kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you pull the kettlebells towards your epaules. Rotate your poignets as you do so. 2. Press one directly overhead by extending through the coudes, turning it so the palm faces forward while holding the other kettlebells stationary . 3. Lower the pressed kettlebells to the position de depart and immediately press with your other arm.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Kettlebell Row', 'Milieu du dos', 'Kettlebell', '1. Place two kettlebells in front of vos pieds. Bend your genoux slightly and push your butt out as much as possible. As you bend over to get into the position de depart grab both kettlebells by the handles. 2. Pull one kettlebells off of le sol while holding on to the other kettlebells. Retract the omoplates of the working side, as you flex the coudes, drawing the kettlebells towards your stomach or rib cage. 3. Lower the kettlebells in the working arm and Repetez with your other arm.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Kettlebell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Alternating Renegade Row', 'Milieu du dos', 'Kettlebell', '1. Place two kettlebells on le sol about epaules width apart. Position yourself on your toes and vos mains as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position vos pieds wide for support. 2. Push one kettlebells into le sol and row the other kettlebells, retracting the omoplates of the working side as you flex the coudes, pulling it to your side. 3. Then lower the kettlebells to le sol and begin the kettlebells in the opposite hand. Repetez for several reps.', 'Muscles secondaires : Abdominaux, Biceps, Pectoraux, Dos, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ankle Circles', 'Mollets', 'Autre', '1. Use a sturdy object like a squat rack to hold yourself. 2. Lift the right leg in the air (just around 2 inches from le sol) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Conseil : One circle equals 1 repetition. Breathe normally as you perform le mouvement. 3. When you are done with the right foot, then Repetez with the left leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ankle On The Knee', 'Fessiers', 'Autre', '1. From a lying position, bend your genoux and keep vos pieds on le sol. 2. Place your ankle of one foot on your opposite genoux. 3. Grasp the cuisses or genoux of the bottom leg and pull both of vos jambes into the poitrine. Relax your neck and epaules. Hold for 10-20 seconds and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ankle_On_The_Knee/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Anterior Tibialis-SMR', 'Mollets', 'Autre', '1. Begin seated on the ground with vos jambes bent and vos pieds on le sol. 2. Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the genoux to above the ankle, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anterior_Tibialis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Anti-Gravity Press', 'Épaules', 'Barre', '1. Place a bar on the ground behind the head of an incline banc. 2. Lay on the banc face down. With a pronated grip, pick the barre up from le sol. Flex the coudes, performing a reverse curl to bring the bar near your poitrine. Position de depart. 3. To begin, press the barre out in front of your head by extending your coudes. Keep vos bras parallel to the ground throughout le mouvement. 4. Revenez en position de depart and Repetez to complete the set.', 'Muscles secondaires : Milieu du dos, Trapèzes, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Anti-Gravity_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Arm Circles', 'Épaules', 'Autre', '1. Stand up and extend vos bras straight out by the sides. The arms should be parallel to le sol and perpendicular (90-degree angle) to your torse. Position de depart. 2. Lentement, start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform le mouvement. 3. Continue the circular motion of the outstretched arms for about ten seconds. Then reverse le mouvement, going the opposite direction.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arm_Circles/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Arnold Dumbbell Press', 'Épaules', 'Haltères', '1. Asseyez-vous sur un banc with back support and hold two halteres in front of you at about upper poitrine level with your palms facing votre corps and your coudes bent. Conseil : vos bras should be next to your torse. The position de depart should look like the contracted portion of a halteres curl. 2. Now to perform le mouvement, raise the halteres as you rotate the palms of vos mains until they are facing forward. 3. Continue lifting the halteres until vos bras are extended above you in straight arm position. Expirez as you perform this portion of le mouvement. 4. Apres une pause, at the top, begin to lower the halteres to the original position by rotating the palms of vos mains towards you. Conseil : The left arm will be rotated in a counter clockwise manner while the right one will be rotated clockwise. Inspirez as you perform this portion of le mouvement. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Around The Worlds', 'Pectoraux', 'Haltères', '1. Lay down on a flat banc holding a halteres in each hand with the palms of the hands facing towards the ceiling. Conseil : vos bras should be parallel to le sol and next to your cuisses. To avoid injury, make sure that you keep your coudes slightly bent. Position de depart. 2. Now move the halteres by creating a semi-circle as you displace them from the initial position to over the head. All of le mouvement should happen with the arms parallel to le sol en permanence. Inspirez as you perform this portion of le mouvement. 3. Reverse le mouvement to return the poids to the position de depart en expirant.', 'Muscles secondaires : Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Around_The_Worlds/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Atlas Stone Trainer', 'Bas du dos', 'Autre', '1. This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe. 2. Begin by loading the desired poids onto the bar. Straddle the poids, wrapping vos bras around the implement, bending at the hips. 3. Begin by pulling the poids up past the genoux, extending through the hips. As the poids clears the genoux, it can be lapped by resting it on your cuisses and sitting back, hugging it tightly to your poitrine. 4. Finish le mouvement by extending through your hips and genoux to raise the poids as high as possible. The poids can be returned to the lap or to the ground for successive repetitions.', 'Muscles secondaires : Biceps, Avant-bras, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stone_Trainer/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Atlas Stones', 'Bas du dos', 'Autre', '1. Begin with the atlas stone between vos pieds. Bend at the hips to wrap vos bras vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold. 2. Pulling the stone into your torse, drive through the back half of vos pieds to pull the stone from the ground. 3. As the stone passes the genoux, lap it by sitting backward, pulling the stone on top of your cuisses. 4. Sit low, getting the stone high onto your poitrine as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.', 'Muscles secondaires : Abdominaux, Adducteurs, Biceps, Mollets, Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stones/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Axle Deadlift', 'Bas du dos', 'Autre', '1. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an over/under grip. 2. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. 3. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 4. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Axle_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Back Flyes - With Bands', 'Épaules', 'Élastique', '1. Run a band around a stationary post like that of a squat rack. 2. Grab the band by the handles and stand back so that the tension in the band rises. 3. Extend and lift the arms straight in front of you. Conseil : vos bras should be straight and parallel to le sol while perpendicular to your torse. vos pieds should be firmly planted on le sol spread at epaules width. Position de depart. 4. en expirant, move vos bras to the sides and back. Keep vos bras extended and parallel to le sol. Continue le mouvement until the arms are extended to your sides. 5. Apres une pause, go back to the original position en inspirant. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Milieu du dos, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Back_Flyes_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Backward Drag', 'Quadriceps', 'Autre', '1. Load a sled with the desired poids, attaching a rope or straps to the sled that you can hold onto. 2. Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Drag/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Backward Medicine Ball Throw', 'Épaules', 'Medecine ball', '1. This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall. 2. Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between vos jambes. 3. Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner. 4. Your partner can then roll the ball back to you. Repetez for the desired number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Backward_Medicine_Ball_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Balance Board', 'Mollets', 'Autre', '1. Place a balance board in front of you. 2. Stand up on it and try to balance yourself. 3. Hold the balance for as long as desired.', 'Muscles secondaires : Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Balance_Board/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Ball Leg Curl', 'Ischio-jambiers', 'Swiss ball', '1. Begin on le sol laying on votre dos with vos pieds on top of the ball. 2. Position the ball so that when vos jambes are extended your ankles are on top of the ball. Position de depart. 3. Raise your hips off of the ground, keeping your poids on the omoplates and vos pieds. 4. Flex the genoux, pulling the ball as close to you as you can, contracting the ischio-jambiers. 5. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Mollets, Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ball_Leg_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Assisted Pull-Up', 'Dos', 'Autre', '1. Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance. 2. Pull the end of the band down, and place one bent genoux into the loop, ensuring it won''t slip out. Take a medium to prise large on the bar. Position de depart. 3. Pull yourself upward by contracting the lats as you flex the coudes. The coudes should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements. 4. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Abdominaux, Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Assisted_Pull-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Good Morning', 'Ischio-jambiers', 'Élastique', '1. Using a 41 inch band, stand on one end, spreading vos pieds a small amount. Bend at the hips to loop the end of the band behind your neck. Position de depart. 2. Keeping vos jambes straight, extend through the hips to come to a near vertical position. 3. Ensure that you do not round votre dos as you go down back to the position de depart.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Good Morning (Pull Through)', 'Ischio-jambiers', 'Élastique', '1. Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. vos mains can help hold the band in position. 2. Begin by bending at the hips, getting your butt back as far as possible. Keep votre dos flat and bend forward to about 90 degrees. Your genoux should be only slightly bent. 3. Revenez en position de depart be driving through with the hips to come back to a standing position.', 'Muscles secondaires : Fessiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Good_Morning_Pull_Through/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Hip Adductions', 'Adducteurs', 'Élastique', '1. Anchor a band around a solid post or other object. 2. Tenez-vous debout avec your left side to the post, and put your right foot through the band, getting it around the ankle. 3. Stand up straight and hold onto the post if needed. Position de depart. 4. Keeping the genoux straight, raise your right legs out to the side as far as you can. 5. Revenez en position de depart and Repetez for the desired rep count. 6. Switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Hip_Adductions/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Pull Apart', 'Épaules', 'Élastique', '1. Begin with vos bras extended straight out in front of you, holding the band with both hands. 2. Initiate le mouvement by performing a reverse fly motion, moving vos mains out laterally to your sides. 3. Keep your coudes extended as you perform le mouvement, bringing the band to your poitrine. Ensure that you keep your epaules back during the exercise. 4. Pause as you complete le mouvement, returning to the position de depart under control.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Pull_Apart/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Band Skull Crusher', 'Triceps', 'Élastique', '1. Secure a band to the base of a rack or the banc. Lay on the banc so that the band is lined up with your head. 2. Take hold of the band, raising your coudes so that the upper arm is perpendicular to le sol. With the coudes flexed, the band should be above your head. Position de depart. 3. Extend through the coudes to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Band_Skull_Crusher/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Ab Rollout', 'Abdominaux', 'Barre', '1. For this exercise you will need to get into a pushup position, but instead of having vos mains of le sol, you will be grabbing on to an Olympic barre (loaded with 5-10 lbs on each side) instead. Position de depart. 2. While keeping a slight arch on votre dos, lift your hips and roll the barre towards vos pieds en expirant. Conseil : As you perform le mouvement, your fessiers should be coming up, you should be keeping the abdominaux tight and should maintain votre dos posture en permanence. Also vos bras should be staying perpendicular to le sol throughout le mouvement. If you don''t, you will work out your epaules and back more than the abdominaux. 3. After a second contraction at the top, start to roll the barre back forward to the position de depart Lentement, en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Bas du dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Ab Rollout - On Knees', 'Abdominaux', 'Barre', '1. Hold an Olympic barre loaded with 5-10lbs on each side and kneel on le sol. 2. Now place the barre on le sol in front of you so that you are on all vos mains and genoux (as in a kneeling push up position). Position de depart. 3. Lentement, roll the barre straight forward, stretching votre corps into a straight position. Conseil : Go down as far as you can without touching le sol with votre corps. Inspirez during this portion of le mouvement. 4. Apres une pause, at the stretched position, start pulling yourself back to the position de depart as you Expirez. Conseil : Go Lentement, and keep your abdominaux tight en permanence.', 'Muscles secondaires : Bas du dos, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Bench Press - Medium Grip', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. From the position de depart, Inspirez and begin coming down Lentement, until the bar touches your middle poitrine. 3. Apres une pause, push the bar back to the position de depart as you Expirez. Focus on pushing the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position at the top of the motion, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : Ideally, lowering the poids should take about twice as long as raising it. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding a barre at a epaules-width grip. The palm of vos mains should be facing forward and the coudes should be close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Conseil : Only the forearms should move. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Curls Lying Against An Incline', 'Biceps', 'Barre', '1. Lie against an incline banc, with vos bras holding a barre and hanging down in a horizontal line. Position de depart. 2. While keeping the upper arms stationary, curl the poids up as high as you can while squeezing the biceps. Expirez as you perform this portion of le mouvement. Conseil : Only the forearms should move. Do not swing the arms. 3. After a second contraction, Lentement, go back to the position de depart en inspirant. Conseil : Make sure that you go all of the way down. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Deadlift', 'Bas du dos', 'Barre', '1. Stand in front of a loaded barre. 2. While keeping the back as straight as possible, bend your genoux, bend forward and grasp the bar using a medium (epaules width) prise en pronation. This will be the position de depart of the exercise. Conseil : If it is difficult to hold on to the bar with this grip, alternate your grip or use poignets straps. 3. While holding the bar, start the lift by pushing with vos jambes while simultaneously getting your torse to the upright position as you Expirez. In the upright position, stick your poitrine out and contract the back by bringing the omoplates back. Think of how the soldiers in the military look when they are in standing in attention. 4. Go back to the position de depart by bending at the genoux while simultaneously leaning the torse forward at the waist while keeping the back straight. When the poids on the bar touch le sol you are back at the position de depart and ready to perform another repetition. 5. Perform the amount of repetitions prescribed in the program.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Ischio-jambiers, Dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Full Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules-width medium stance with the toes slightly pointed out. Keep your head up en permanence and maintain a straight back. Position de depart. 4. Begin to Lentement, lower the bar by bending the genoux and sitting back with your hips as you maintain a straight posture with the head up. Continue down until your ischio-jambiers are on your mollets. Inhale as you perform this portion of le mouvement. 5. Begin to raise the bar en expirant by pushing le sol with the heel or middle of your foot as you straighten the legs and extend the hips to go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Full_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Glute Bridge', 'Fessiers', 'Barre', '1. Begin seated on the ground with a loaded barre over vos jambes. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on le sol. 2. Begin le mouvement by driving through with your heels, extending your hips vertically through the bar. Your poids should be supported by your upper back and the heels of vos pieds. 3. Extend as far as possible, then reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Glute_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Guillotine Bench Press', 'Pectoraux', 'Barre', '1. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with vos bras locked. Position de depart. 2. As you Inspirez, bring the bar down Lentement, until it is about 1 inch from your neck. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Guillotine_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Hack Squat', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre behind you bras tendus and vos pieds at epaules width. Conseil : A epaules width grip is best with the palms of vos mains facing back. You can use poignets wraps for this exercise for a better grip. Position de depart. 2. While keeping your head and eyes up and back straight, squat until your upper cuisses are parallel to le sol. Inspirez as you Lentement, go down. 3. Pressing mainly with the heel of the foot and squeezing the cuisses, go back up as you Expirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Avant-bras, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hack_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Hip Thrust', 'Fessiers', 'Barre', '1. Begin seated on the ground with a banc directly behind you. Have a loaded barre over vos jambes. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. 2. Roll the bar so that it is directly above your hips, and lean back against the banc so that your omoplates are near the top of it. 3. Begin le mouvement by driving through vos pieds, extending your hips vertically through the bar. Your poids should be supported by your omoplates and vos pieds. Extend as far as possible, then reverse the motion to Revenez en position de depart.', 'Muscles secondaires : Mollets, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Incline Bench Press - Medium Grip', 'Pectoraux', 'Barre', '1. Allongez-vous au sol on an incline banc. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on you upper poitrine. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : it should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Incline Shoulder Raise', 'Épaules', 'Barre', '1. Allongez-vous au sol on an Incline banc. Using a prise moyenne (a grip that is slightly wider than epaules width), lift the bar from the rack and hold it straight over you with vos bras straight. Position de depart. 2. While keeping the arms straight, lift the bar by protracting your omoplates, raising the epaules from the banc as you Expirez. 3. Bring back the bar to the position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Incline_Shoulder_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Lunge', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torse upright and maintaining balance. Inhale as you go down. Note: Do not allow your genoux to go forward beyond your toes as you come down, as this will put undue stress on the genoux joint. li> 4. Using mainly the heel of your foot, push up and go back to the position de depart en expirant. 5. Repetez le mouvement for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Rear Delt Row', 'Épaules', 'Barre', '1. Stand up straight while holding a barre using a wide (higher than epaules width) and overhand (palms facing votre corps) grip. 2. Bend genoux slightly and bend over as you keep the natural arch of votre dos. Let the arms hang in front of you as they hold the bar. Once your torse is parallel to le sol, flare the coudes out and away from votre corps. Conseil : Your torse and vos bras should resemble the letter "T". Now you are ready to begin the exercise. 3. While keeping the upper arms perpendicular to the torse, pull the barre up towards your upper poitrine as you squeeze the rear delts and you Expirez. Conseil : When performed correctly, this exercise should resemble a banc press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks. 4. Lentement, go back to the initial position as you Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rear_Delt_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Rollout from Bench', 'Abdominaux', 'Barre', '1. Place a loaded barre on the ground, near the end of a banc. Kneel with both legs on the banc, and take a medium to prise serree on the barre. Position de depart. 2. To begin, extend through the hips to Lentement, roll the bar forward. As you roll out, flex the epaules to roll the bar above your head. Ensure that vos bras remain extended throughout le mouvement. 3. When the bar has been moved as far forward as possible, Revenez en position de depart.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Rollout_from_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Seated Calf Raise', 'Mollets', 'Barre', '1. Place a block about 12 inches in front of a flat banc. 2. Sit on the banc and place the ball of vos pieds on the block. 3. Have someone place a barre over your upper cuisses about 3 inches above your genoux and hold it there. Position de depart. 4. Raise up on your toes as high as possible as you squeeze the mollets and as you Expirez. 5. After a second contraction, Lentement, go back to the position de depart. Conseil : To get maximum benefit stretch your mollets as far as you can. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Seated_Calf_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shoulder Press', 'Épaules', 'Barre', '1. Asseyez-vous sur un banc with back support in a squat rack. Position a barre at a height that is just above your head. Grab the barre with a pronated grip (palms facing forward). 2. Once you pick up the barre with the correct grip width, lift the bar up over your head by locking vos bras. Hold at about epaules level and slightly in front of your head. Position de depart. 3. Lower the bar down to the epaules Lentement, en inspirant. 4. Lift the bar back up to the position de depart en expirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shrug', 'Trapèzes', 'Barre', '1. Tenez-vous debout avec vos pieds at epaules width as you hold a barre with both hands in front of you using a pronated grip (palms facing the cuisses). Conseil : vos mains should be a little wider than epaules width apart. You can use poignets wraps for this exercise for a better grip. Position de depart. 2. Raise your epaules up as far as you can go as you Expirez and hold the contraction for a second. Conseil : Refrain from trying to lift the barre by using your biceps. 3. Lentement, Revenez en position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Shrug Behind The Back', 'Trapèzes', 'Barre', '1. Tenez-vous debout avec vos pieds at epaules width as you hold a barre with both hands behind votre dos using a pronated grip (palms facing back). Conseil : vos mains should be a little wider than epaules width apart. You can use poignets wraps for this exercise for better grip. Position de depart. 2. Raise your epaules up as far as you can go as you Expirez and hold the contraction for a second. Conseil : Refrain from trying to lift the barre by using your biceps. The arms should remain stretched out en permanence. 3. Lentement, Revenez en position de depart as you Inspirez. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug_Behind_The_Back/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Side Bend', 'Abdominaux', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck). vos pieds should be epaules width apart. Position de depart. 2. While keeping votre dos straight and your head up, bend only at the waist to the right as far as possible. Inspirez as you bend to the side. Then Maintenez 1 seconde and come back up to the position de depart en expirant. Conseil : Keep the rest of the body stationary. 3. Now Repetez le mouvement but bending to the left instead. Maintenez 1 seconde and come back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Bend/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Side Split Squat', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck). vos pieds should be placed wide apart with the foot of the lead leg angled out to the side. Position de depart. 2. Lower votre corps towards the side of your angled foot by bending the genoux and hip of your lead leg and while keeping the opposite leg only slightly bent. Inspirez as you lower votre corps. 3. Revenez en position de depart by extending the hip and genoux of the lead leg. Expirez as you perform this movement. 4. After performing the recommended amount of reps, Repetez le mouvement with the opposite leg.', 'Muscles secondaires : Mollets, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Side_Split_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Squat', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below epaules level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 2. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 3. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 4. Begin to Lentement, lower the bar by bending the genoux and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the mollets becomes slightly less than 90-degrees. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 5. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs again and go back to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Squat To A Bench', 'Quadriceps', 'Barre', '1. This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat banc or a box behind you. The flat banc is used to teach you to set your hips back and to hit depth. 2.  3. Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your epaules (slightly below the neck) across it. 4. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with vos jambes and at the same time straightening your torse. 5. Step away from the rack and position vos jambes using a epaules width medium stance with the toes slightly pointed out. Keep your head up en permanence as looking down will get you off balance and also maintain a straight back. Position de depart. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section). 6. Begin to Lentement, lower the bar by bending the genoux and sitting your hips back as you maintain a straight posture with the head up. Continue down until you slightly touch the banc behind you. Inhale as you perform this portion of le mouvement. Conseil : If you performed the exercise correctly, the front of the genoux should make an imaginary straight line with the toes that is perpendicular to the front. If your genoux are past that imaginary line (if they are past your toes) then you are placing undue stress on the genoux and the exercise has been performed incorrectly. 7. Begin to raise the bar en expirant by pushing le sol with the heel of your foot as you straighten the legs and extend the hips to go back to the position de depart. 8. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat_To_A_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Step Ups', 'Quadriceps', 'Barre', '1. Stand up straight while holding a barre placed on the back of your epaules (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat banc). Position de depart. 2. Place the right foot on the elevated platform. Step on the platform by extending the hip and the genoux of your right leg. Use the heel mainly to lift the rest of votre corps up and place the foot of the left leg on the platform as well. Expirez as you execute the force required to come up. 3. Step down with the left leg by flexing the hip and genoux of the right leg en inspirant. Return to the original standing position by placing the right foot of to next to the left foot on the initial position. 4. Repetez with the right leg for the recommended amount of repetitions and then perform with the left leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Step_Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Barbell Walking Lunge', 'Quadriceps', 'Barre', '1. Begin standing with vos pieds epaules width apart and a barre across your upper back. 2. Step forward with one leg, flexing the genoux to drop your hips. Descend until your rear genoux nearly touches the ground. Your posture should remain upright, and your front genoux should stay above the front foot. 3. Drive through the heel of your lead foot and extend both genoux to raise yourself back up. 4. Step forward with your rear foot, Repetezing the lunge on the opposite leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Walking_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Battling Ropes', 'Épaules', 'Autre', '1. For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with vos bras extended at your side. Position de depart. 2. Initiate le mouvement by rapidly raising one arm to epaules level as quickly as you can. 3. As you let that arm drop to the position de depart, raise the opposite side. 4. Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.', 'Muscles secondaires : Pectoraux, Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Battling_Ropes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bear Crawl Sled Drags', 'Quadriceps', 'Autre', '1. Wearing either a harness or a loose poids belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that vos mains are on the ground. votre dos should be flat and genoux bent. Position de depart. 2. Begin by driving with legs, alternating left and right. Use vos mains to maintain balance and to help pull. Try to keep votre dos flat as you move over a given distance.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bear_Crawl_Sled_Drags/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Behind Head Chest Stretch', 'Pectoraux', 'Autre', '1. Sit upright on le sol with your partner behind you. 2. Place vos mains behind your hand, and push your coudes back as far as you can. Your partner should hold your coudes. Position de depart. 3. Gently attempt to pull your coudes forward with vos mains still behind your head for 10 or more seconds. Your partner should prevent your coudes from moving. 4. Now, relax your muscles and have your partner gently pull the coudes back as far as it comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.', 'Muscles secondaires : Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Behind_Head_Chest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Dips', 'Triceps', 'Poids de corps', '1. For this exercise you will need to place a banc behind votre dos. With the banc perpendicular to votre corps, and while looking away from it, hold on to the banc on its edge with the hands fully extended, separated at epaules width. The legs will be extended forward, bent at the waist and perpendicular to your torse. Position de depart. 2. Lentement, lower votre corps en inspirant by bending at the coudes until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Conseil : Keep the coudes as close as possible throughout le mouvement. Forearms should always be pointing down. 3. Using your triceps to bring your torse up again, lift yourself back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Jump', 'Quadriceps', 'Poids de corps', '1. Begin with a box or banc 1-2 feet in front of you. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Perform a short squat in preparation for the jump; swing vos bras behind you. 3. Rebound out of this position, extending through the hips, genoux, and ankles to jump as high as possible. Swing vos bras forward and up. 4. Jump over the banc, landing with the genoux bent, absorbing the impact through the legs. 5. Turn around and face the opposite direction, then jump back over the banc.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Jump/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press - Powerlifting', 'Triceps', 'Barre', '1. Begin by lying on the banc, getting your head beyond the bar if possible. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 2. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. 3. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press - With Bands', 'Pectoraux', 'Élastique', '1. Using a flat banc secure a band under the leg of the banc that is nearest to your head. 2. Once the band is secure, grab it by both handles and lie down on the banc. 3. Extend vos bras so that you are holding the band handles in front of you at epaules width. 4. Once at epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. Position de depart. 5. Bring down the handles Lentement, until your coudes forms a 90 degree angle. Keep full control en permanence. 6. As you Expirez, bring the handles up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up. 7. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Press with Chains', 'Triceps', 'Barre', '1. Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar. 2. Lying on the banc, get your head beyond the bar if possible. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. However wide your grip, it should cover the ring on the bar. 3. Pull the bar out of the rack without protracting your epaules. Focus on squeezing the bar and trying to pull it apart. Lower the bar to your lower poitrine or upper stomach. The bar, poignets, and coudes should stay in line en permanence. 4. Pause when the barre touches your torse, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Dos, Épaules. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bench Sprint', 'Quadriceps', 'Autre', '1. Stand on the ground with one foot resting on a banc or box with your heel close to the edge. 2. Push off with your foot on top of the banc, extending through the hip and genoux. 3. Land with the opposite foot on top of the box, returning your other foot back to the start position. 4. Continue alternating from one foot to another to complete the set.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Sprint/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Arm Barbell Pullover', 'Dos', 'Barre', '1. Allongez-vous sur un banc plat with a barre using a epaules grip width. 2. Hold the bar straight over your poitrine with a bend in vos bras. Position de depart. 3. While keeping vos bras in the bent arm position, lower the poids Lentement, in an arc behind your head while breathing in until you feel a stretch on the poitrine. 4. At that point, bring the barre back to the position de depart using the arc through which the poids was lowered and exhale as you perform this movement. 5. Hold the poids on the initial position for a second and Repetez the motion for the prescribed number of repetitions.', 'Muscles secondaires : Pectoraux, Dos, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Barbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Arm Dumbbell Pullover', 'Pectoraux', 'Haltères', '1. Place a halteres standing up on a flat banc. 2. Ensuring that the halteres stays securely placed at the top of the banc, lie perpendicular to the banc (torse across it as in forming a cross) with only your epaules lying on the surface. Hips should be below the banc and legs bent with feet firmly on le sol. The head will be off the banc as well. 3. Grasp the halteres with both hands and hold it straight over your poitrine with a bend in vos bras. Both palms should be pressing against the underside one of the sides of the halteres. Position de depart. Caution: Always ensure that the halteres used for this exercise is secure. Using a halteres with loose plates can result in the halteres falling apart and falling on your face. 4. While keeping vos bras locked in the bent arm position, lower the poids Lentement, in an arc behind your head while breathing in until you feel a stretch on the poitrine. 5. At that point, bring the halteres back to the position de depart using the arc through which the poids was lowered and exhale as you perform this movement. 6. Hold the poids on the initial position for a second and Repetez the motion for the prescribed number of repetitions.', 'Muscles secondaires : Dos, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Arm_Dumbbell_Pullover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent-Knee Hip Raise', 'Abdominaux', 'Poids de corps', '1. Lay flat on le sol with vos bras next to your sides. 2. Now bend your genoux at around a 75 degree angle and lift vos pieds off le sol by around 2 inches. 3. Using your lower abdominaux, bring your genoux in towards you as you maintain the 75 degree angle bend in vos jambes. Continue this movement until you raise your hips off of le sol by rolling your pelvis backward. Expirez as you perform this portion of le mouvement. Conseil : At the end of le mouvement your genoux will be over your poitrine. 4. Squeeze your abdominaux at the top of le mouvement for a second and then Revenez en position de depart Lentement, as you Inspirez. Conseil : Maintain a controlled motion en permanence. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent-Knee_Hip_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Barbell Row', 'Milieu du dos', 'Barre', '1. Holding a barre with a pronated grip (palms facing down), bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The barre should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. Now, while keeping the torse stationary, Expirez and lift the barre to you. Keep the coudes close to the body and only use the forearms to hold the poids. At the top contracted position, squeeze the back muscles and hold for a brief pause. 3. Then inhale and Lentement, lower the barre back to the position de depart. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Barbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'Épaules', 'Haltères', '1. Stand up straight while holding a halteres in each hand and with an incline banc in front of you. 2. While keeping votre dos straight and maintaining the natural arch of votre dos, lean forward until your forehead touches the banc in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of vos mains should be facing each other and your torse should be parallel to le sol. Position de depart. 3. Keeping your torse forward and stationary, and the arms straight with a slight bend at the coudes, lift the halteres straight to the side until both arms are parallel to le sol. Exhale as you lift the poids. Caution: avoid swinging the torse or bringing the arms back as opposed to the side. 4. After a one second contraction at the top, Lentement, lower the halteres back to the position de depart. 5. Repetez the recommended amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Low-Pulley Side Lateral', 'Épaules', 'Poulie', '1. Select a poids and hold the handle of the low pulley with your right hand. 2. Bend at the waist until your torse is nearly parallel to le sol. vos jambes should be slightly bent with your left hand placed on your lower left cuisses. Your right arm should be hanging from your epaules in front of you and with a slight bend at the coudes. Position de depart. 3. Raise your right arm, coudes slightly bent, to the side until the arm is parallel to le sol and in line with your right ear. Expirez as you perform this step. 4. Lentement, lower the poids back to the position de depart as you Inspirez. 5. Repetez selon le nombre souhaite. and Repetez le mouvement with the other arm.', 'Muscles secondaires : Bas du dos, Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over One-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Put poids on one of the ends of an Olympic barre. Make sure that you either place the other end of the barre in the corner of two walls; or put a heavy object on the ground so the barre cannot slide backward. 2. Bend forward until your torse is as close to parallel with le sol as you can and keep your genoux slightly bent. 3. Now grab the bar with one arm just behind the plates on the side where the poids was placed and put your other hand on your genoux. Position de depart. 4. Pull the bar straight up with your coudes in (to maximize back stimulation) until the plates touch your lower poitrine. Squeeze the back muscles as you lift the poids up and Maintenez 1 seconde at the top of le mouvement. Expirez as you lift the poids. Conseil : Do not allow for any swinging of the torse. Only the arm should move. 5. Lentement, lower the bar to the position de depart getting a nice stretch on the lats. Conseil : Do not let the plates touch le sol. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones). 6. Repetez selon le nombre souhaite. and switch arms.', 'Muscles secondaires : Biceps, Dos, Bas du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Arm Long Bar Row', 'Milieu du dos', 'Barre', '1. Put poids on one of the ends of an Olympic barre. Make sure that you either place the other end of the barre in the corner of two walls; or put a heavy object on the ground so the barre cannot slide backward. 2. Bend forward until your torse is as close to parallel with le sol as you can and keep your genoux slightly bent. 3. Now grab the bar with both arms just behind the plates on the side where the poids was placed and put your other hand on your genoux. Position de depart. 4. Pull the bar straight up with your coudes in (to maximize back stimulation) until the plates touch your lower poitrine. Squeeze the back muscles as you lift the poids up and Maintenez 1 seconde at the top of le mouvement. Expirez as you lift the poids. Conseil : Use a stirrup or double handle cable attachment by hooking it under the end of the bar. 5. Lentement, lower the bar to the position de depart getting a nice stretch on the lats. Conseil : Do not let the plates touch le sol. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones). 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Arm_Long_Bar_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Dumbbell Row', 'Milieu du dos', 'Haltères', '1. With a halteres in each hand (palms facing your torse), bend your genoux slightly and bring your torse forward by bending at the waist; as you bend make sure to keep votre dos straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The poids should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. While keeping the torse stationary, lift the halteres to your side (as you Expirez), keeping the coudes close to the body (do not exert any force with the forearm other than holding the poids). On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 3. Lentement, lower the poids again to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Over Two-Dumbbell Row With Palms In', 'Milieu du dos', 'Haltères', '1. With a halteres in each hand (palms facing each other), bend your genoux slightly and bring your torse forward, by bending at the waist, while keeping the back straight until it is almost parallel to le sol. Conseil : Make sure that you keep the head up. The poids should hang directly in front of you as vos bras hang perpendicular to le sol and your torse. Position de depart. 2. While keeping the torse stationary, lift the halteres to your side as you Expirez, squeezing your omoplates together. On the top contracted position, squeeze the back muscles and Maintenez 1 seconde. 3. Lentement, lower the poids again to the position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bent Press', 'Abdominaux', 'Kettlebell', '1. Clean a kettlebells to your epaules. Clean the kettlebells to your epaules by extending through the legs and hips as you raise the kettlebells towards your epaules. The poignets should rotate as you do so. Position de depart. 2. Begin my leaning to the side opposite the kettlebells, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebells. As you do so, press the poids vertically be extending through the coudes, keeping your arm perpendicular to the ground. 3. Return to an upright position, with the kettlebells above your head. Return the kettlebells to the epaules and Repetez for the desired number of repetitions.', 'Muscles secondaires : Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Épaules, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bicycling', 'Quadriceps', 'Autre', '1. To begin, seat yourself on the bike and adjust the seat to your height.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bicycling, Stationary', 'Quadriceps', 'Machine', '1. To begin, seat yourself on the bike and adjust the seat to your height. 2. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and poids to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bicycling_Stationary/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Board Press', 'Triceps', 'Barre', '1. Begin by lying on the banc, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt. 2. Tuck vos pieds underneath you and arch votre dos. Using the bar to help support your poids, lift your epaules off the banc and retract them, squeezing the omoplates together. Use vos pieds to drive your traps into the banc. Maintain this tight body position throughout le mouvement. 3. You can take a standard banc grip, or epaules width to focus on the triceps. Pull the bar out of the rack without protracting your epaules. The bar, poignets, and coudes should stay in line en permanence. Focus on squeezing the bar and trying to pull it apart. 4. Lower the bar to the boards, and then drive the bar up with as much force as possible. The coudes should be tucked in until lockout.', 'Muscles secondaires : Pectoraux, Avant-bras, Dos, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Body-Up', 'Triceps', 'Poids de corps', '1. Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torse straight. Your forearms should be epaules-width apart. Position de depart. 2. Pressing your palms firmly into the ground, extend through the coudes to raise votre corps from the ground. Keep your torse rigid as you perform le mouvement. 3. Lentement, lower your forearms back to the ground by allowing the coudes to flex. 4. Repetez.', 'Muscles secondaires : Abdominaux, Avant-bras. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Body Tricep Press', 'Triceps', 'Poids de corps', '1. Position a bar in a rack at poitrine height. 2. Standing, take a epaules width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. Position de depart. 3. Begin by flexing the coudes, lowering yourself towards the bar. 4. Pause, and then reverse the motion by extending the coudes. 5. Progress from bodyweight by adding chains over your epaules.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Body_Tricep_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Flyes', 'Pectoraux', 'Barre EZ', '1. Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll. 2. Assume a push-up position over the bars, supporting your poids on your toes and hands with vos bras extended and body straight. 3. Place vos mains on the bars. Position de depart. 4. Using a slow and controlled motion, move vos mains away from the midline of votre corps, rolling the bars apart. Inhale during this portion of the motion. 5. After moving the bars as far apart as you can, Revenez en position de depart by pulling them back together. Exhale as you perform this movement.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Flyes/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Mid Row', 'Milieu du dos', 'Autre', '1. Begin by taking a medium to prise large on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your genoux to your poitrine, leaning back and getting vos jambes over your side of the pull-up apparatus. Position de depart. 2. Beginning with vos bras straight, flex the coudes and retract the omoplates to raise votre corps up until vos jambes contact the pull-up apparatus. 3. Apres une pause, Revenez en position de depart.', 'Muscles secondaires : Biceps, Dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Mid_Row/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Squat', 'Quadriceps', 'Poids de corps', '1. Tenez-vous debout avec vos pieds epaules width apart. You can place vos mains behind your head. Position de depart. 2. Begin le mouvement by flexing your genoux and hips, sitting back with your hips. 3. Continue down to full depth if you are able,and quickly reverse the motion until you Revenez en position de depart. As you squat, keep your head and poitrine up and push your genoux out.', 'Muscles secondaires : Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bodyweight Walking Lunge', 'Quadriceps', 'Autre', '1. Begin standing with vos pieds epaules width apart and vos mains on your hips. 2. Step forward with one leg, flexing the genoux to drop your hips. Descend until your rear genoux nearly touches the ground. Your posture should remain upright, and your front genoux should stay above the front foot. 3. Drive through the heel of your lead foot and extend both genoux to raise yourself back up. 4. Step forward with your rear foot, Repetezing the lunge on the opposite leg.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bodyweight_Walking_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bosu Ball Cable Crunch With Side Bends', 'Abdominaux', 'Poulie', '1. Connect a standard handle to each arm of a cable machine, and position them in the most downward position. 2. Grab a Bosu Ball and position it in front and center of the cable machine. 3. Lie down on the Bosu Ball with the small of votre dos arched around the ball. Your rear end should be close to le sol without touching it. 4. With both hands, reach back and grab the handle of each cable. 5. With vos pieds positioned in a wide stance, extend vos bras straight out in front of you and in between your genoux. vos mains should be at genoux level. 6. Keep vos bras straight and in-line with the upward angle of the cable. Elevate your torse in a crunching motion without dropping or bending vos bras. 7. Maintain the rigid position with vos bras. Lentement, descend back to the position de depart with votre dos arched around the Bosu Ball and your abdominals elongated. 8. Repetez the same series of movements to failure. 9. Once you reach failure, keep your abdominaux tight and raise your torse into plank position so votre dos is elevated off the Bosu Ball. 10. Lower vos bras down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bottoms-Up Clean From The Hang Position', 'Avant-bras', 'Kettlebell', '1. Initiate the exercise by standing upright with a kettlebells in one hand. 2. Swing the kettlebells back forcefully and then reverse the motion forcefully. Crush the kettlebells handle as hard as possible and raise the kettlebells to your epaules.', 'Muscles secondaires : Biceps, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bottoms Up', 'Abdominaux', 'Poids de corps', '1. Begin by lying on votre dos on the ground. vos jambes should be straight and vos bras at your side. Position de depart. 2. To perform le mouvement, tuck the genoux toward your poitrine by flexing the hips and genoux. Following this, extend vos jambes directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your fessiers from le sol. 3. Apres une pause, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bottoms_Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Jump (Multiple Response)', 'Ischio-jambiers', 'Autre', '1. Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent. 2. Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform. 3. Immediately drop or jump back down to the original starting place; then Repetez the sequence.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Jump_Multiple_Response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Skip', 'Ischio-jambiers', 'Autre', '1. You will need several boxes lined up about 8 feet apart. 2. Begin facing the first box with one leg slightly behind the other. 3. Drive off the back leg, attempting to gain as much height with the hips as possible. 4. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box. 5. Then, step to the next box and Repetez.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Skip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat', 'Quadriceps', 'Barre', '1. The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe.', 'Muscles secondaires : Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat with Bands', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or halteres so that there is appropriate tension. If halteres are used, secure them so that they don''t move. Also, ensure that the halteres you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the halteres down. If more tension is needed, you can either widen the base on le sol or choke the bands. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 3. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 4. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe. Use care to return the barre to the rack.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Box Squat with Chains', 'Quadriceps', 'Barre', '1. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. 2. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on le sol at the top of le mouvement. 3. Begin by stepping under the bar and placing it across the back of the epaules. Squeeze your omoplates together and rotate your coudes forward, attempting to bend the bar across your epaules. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place vos pieds wider for more emphasis on the back, fessiers, adductors, and ischio-jambiers, or closer together for more quad development. Keep your head facing forward. 4. With votre dos, epaules, and sangle abdominale tight, push your genoux and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box. 5. Keeping the poids on your heels and pushing vos pieds and genoux out, drive upward off of the box as you lead le mouvement with your head. Continue upward, maintaining tightness head to toe.', 'Muscles secondaires : Abducteurs, Adducteurs, Mollets, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Box_Squat_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Brachialis-SMR', 'Biceps', 'Foam roller', '1. Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with votre corps, with the outside of the biceps pressed against the foam roller. 2. Raise your hips off of le sol, supporting your poids on your arm and on vos pieds. Hold for 10-30 seconds, and then switch sides.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Brachialis-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Bradford/Rocky Presses', 'Épaules', 'Barre', '1. Sit on a Military Press banc with a bar at epaules level with a pronated grip (palms facing forward). Conseil : Your grip should be wider than epaules width and it should create a 90-degree angle between the forearm and the upper arm as the barre goes down. Position de depart. 2. Once you pick up the barre with the correct grip, lift the bar up over your head by locking vos bras. 3. Now lower the bar down to the back of the head Lentement, en inspirant. 4. Lift the bar back up to the position de depart en expirant. 5. Lower the bar down to the position de depart Lentement, en inspirant. This is one repetition. 6. Alternate in this manner until you complete the recommended amount of repetitions.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bradford_Rocky_Presses/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butt-Ups', 'Abdominaux', 'Poids de corps', '1. Begin a pushup position but with your coudes on the ground and resting on your forearms. vos bras should be bent at a 90 degree angle. 2. Arch votre dos slightly out rather than keeping votre dos completely straight. 3. Raise your fessiers toward the ceiling, squeezing your abdominaux tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of le mouvement. 4. Lower back down Lentement, to your position de depart as you Inspirez. Conseil : Don''t let votre dos sag downwards. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt-Ups/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butt Lift (Bridge)', 'Fessiers', 'Poids de corps', '1. Allongez-vous au sol on votre dos with the hands by your side and your genoux bent. vos pieds should be placed around epaules width. Position de depart. 2. Pushing mainly with your heels, lift your hips off le sol while keeping votre dos straight. Expirez as you perform this part of the motion and hold at the top for a second. 3. Lentement, go back to the position de depart as you Inspirez.', 'Muscles secondaires : Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butt_Lift_Bridge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Butterfly', 'Pectoraux', 'Machine', '1. Sit on the machine with votre dos flat on the pad. 2. Take hold of the handles. Conseil : Your upper arms should be positioned parallel to le sol; adjust the machine accordingly. Position de depart. 3. Push the handles together Lentement, as you squeeze your poitrine in the middle. Expirez during this part of the motion and hold the contraction for a second. 4. Return back to the position de depart Lentement, en inspirant until your poitrine muscles are fully stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Butterfly/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Chest Press', 'Pectoraux', 'Poulie', '1. Adjust the poids to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and poitrine up. The coudes should be bent to about 90 degrees. Position de depart. 2. Begin by extending through the coudes, pressing the handles together straight in front of you. Keep your omoplates retracted as you execute le mouvement. 3. After pausing at full extension, return to th position de depart, keeping tension on the cables. 4. You can also execute this movement with votre dos off the pad, at an incline or decline, or alternate hands.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Chest_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Crossover', 'Pectoraux', 'Poulie', '1. To get yourself into the position de depart, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand. 2. Step forward in front of an imaginary straight line between both pulleys while pulling vos bras together in front of you. Your torse should have a small forward bend from the waist. Position de depart. 3. With a slight bend on your coudes in order to prevent stress at the biceps tendon, extend vos bras to the side (straight out at both sides) in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms and torse should remain stationary; le mouvement should only occur at the epaules joint. 4. Return vos bras back to the position de depart as you Expirez. Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the position de depart and Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crossover/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Crunch', 'Abdominaux', 'Poulie', '1. Kneel below a high pulley that contains a rope attachment. 2. Grasp cable rope attachment and lower the rope until vos mains are placed next to your face. 3. Flex your hips slightly and allow the poids to hyperextend the lower back. Position de depart. 4. With the hips stationary, flex the waist as you contract the abdominaux so that the coudes travel towards the middle of the cuisses. Exhale as you perform this portion of le mouvement and hold the contraction for a second. 5. Lentement, Revenez en position de depart en inspirant. Conseil : Make sure that you keep constant tension on the abdominaux throughout le mouvement. Also, do not choose a poids so heavy that the lower back handles the brunt of the work. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Deadlifts', 'Quadriceps', 'Poulie', '1. Move the cables to the bottom of the towers and select an appropriate poids. Stand directly in between the uprights. 2. To begin, squat down be flexing your hips and genoux until you can reach the handles. 3. After grasping them, begin your ascent. Driving through your heels extend your hips and genoux keeping vos mains hanging at your side. Keep your head and poitrine up throughout le mouvement. 4. After reaching a full standing position, Revenez en position de depart and Repetez.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Deadlifts/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Hammer Curls - Rope Attachment', 'Biceps', 'Poulie', '1. Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it. 2. Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torse stationary. 3. Put your coudes in by your side and keep them there stationary during the entire movement. Conseil : Only the forearms should move; not your upper arms. Position de depart. 4. Using your biceps, pull vos bras up en expirant until your biceps touch your forearms. Conseil : Remember to keep the coudes in and your upper arms stationary. 5. After a 1 second contraction where you squeeze your biceps, Lentement, start to bring the poids back to the original position. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Hip Adduction', 'Quadriceps', 'Poulie', '1. Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away. 2. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. 3. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. 4. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. Position de depart. 5. Now perform le mouvement by moving the leg with the ankle cuff in front of the far leg by using the inner cuisses to abduct the hip. Expirez during this portion of le mouvement. 6. Lentement, Revenez en position de depart as you Inspirez. 7. Repetez selon le nombre souhaite. and then Repetez the same movement with the opposite leg.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Hip_Adduction/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Incline Pushdown', 'Dos', 'Poulie', '1. Lie on incline an banc facing away from a high pulley machine that has a straight bar attachment on it. 2. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) epaules width grip and extend vos bras in front of you. The bar should be around 2 inches away from your upper cuisses. Position de depart. 3. Keeping the upper arms stationary, lift vos bras back in a semi circle until the bar is straight over your head. Inspirez during this portion of le mouvement. 4. Lentement, go back to the position de depart using your lats and hold the contraction once you reach the position de depart. Expirez during the execution of this movement. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Pushdown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Incline Triceps Extension', 'Triceps', 'Poulie', '1. Lie on incline an banc facing away from a high pulley machine that has a straight bar attachment on it. 2. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) prise serree (less than epaules width) and keep your coudes tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from le sol. 3. Keeping the upper arms stationary, extend the arms as you flex the triceps. Expirez during this portion of le mouvement and hold the contraction for a second. 4. Lentement, go back to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Incline_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Internal Rotation', 'Épaules', 'Poulie', '1. Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Conseil : If you can adjust the pulley''s height, you can use a flat banc to sit on instead. 2. Position the coudes against your side with the coudes bent at 90° and the arm pointing towards the pulley. Position de depart. 3. Pull the single hand cable attachment toward votre corps by internally rotating your epaules until your forearm is across your abdominaux. You will be creating an imaginary semi-circle. Conseil : The forearm should be perpendicular to your torse en permanence. 4. Lentement, go back to the initial position. 5. Repetez selon le nombre souhaite. and then Repetez le mouvement with the next arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Internal_Rotation/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Iron Cross', 'Pectoraux', 'Poulie', '1. Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. 2. Stand directly between both pulleys with vos bras extended out to your sides. Your head and poitrine should be up while vos bras form a "T". Position de depart. 3. Keeping the coudes extended, pull vos bras straight to your sides. 4. Return vos bras back to the position de depart Apres une pause, at the peak contraction. 5. Continue le mouvement for the prescribed number of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Iron_Cross/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Judo Flip', 'Abdominaux', 'Poulie', '1. Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Tenez-vous debout avec your side to the cable with a wide stance, and grab the rope with both hands. 2. Twist votre corps away from the pulley as you bring the rope over your epaules like you''re performing a judo flip. 3. Shift your poids between vos pieds as you twist and crunch forward, pulling the cable downward. 4. Revenez en position de depart and Repetez until failure. 5. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Judo_Flip/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Lying Triceps Extension', 'Triceps', 'Poulie', '1. Allongez-vous sur un banc plat and grasp the straight bar attachment of a low pulley with a narrow prise en pronation. Conseil : The easiest way to do this is to have someone hand you the bar as you lay down. 2. With vos bras extended, position the bar over your torse. vos bras and your torse should create a 90-degree angle. Position de depart. 3. Lower the bar by bending at the coudes while keeping the upper arms stationary and coudes in. Go down until the bar lightly touches your forehead. Inspirez as you perform this portion of le mouvement. 4. Flex the triceps as you lift the bar back to its position de depart. Exhale as you perform this portion of le mouvement. 5. Maintenez 1 seconde at the contracted position and Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Lying_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable One Arm Tricep Extension', 'Triceps', 'Poulie', '1. With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the poids stack. 2. Now pull the handle down so that your upper arm and coudes are locked in to the side of votre corps. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. Position de depart. 3. As you contract the triceps, move the single handle attachment down to your side until your arm is straight. Expirez as you perform this movement. Conseil : Only the forearms should move. Your upper arms should remain stationary en permanence. 4. Squeeze the triceps and Maintenez 1 seconde in this contracted position. 5. Lentement, return the handle to the position de depart. 6. Repetez selon le nombre souhaite. and then perform the same movement with the other arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_One_Arm_Tricep_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Preacher Curl', 'Biceps', 'Poulie', '1. Place a preacher banc about 2 feet in front of a pulley machine. 2. Attach a straight bar to the low pulley. 3. Sit at the preacher banc with your coudes and upper arms firmly on top of the banc pad and have someone hand you the bar from the low pulley. 4. Grab the bar and fully extend vos bras on top of the preacher banc pad. Position de depart. 5. Now start pilling the poids up towards your epaules and squeeze the biceps hard at the top of le mouvement. Exhale as you perform this motion. Also, Maintenez 1 seconde at the top. 6. Now Lentement, lower the poids to the position de depart. 7. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Preacher_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rear Delt Fly', 'Épaules', 'Poulie', '1. Adjust the pulleys to the appropriate height and adjust the poids. The pulleys should be above your head. 2. Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. Position de depart. 3. Initiate le mouvement by moving vos bras back and outward, keeping vos bras straight as you execute le mouvement. 4. Pause at the end of the motion before returning the handles to the start position.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rear_Delt_Fly/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Reverse Crunch', 'Abdominaux', 'Poulie', '1. Connect an ankle strap attachment to a low pulley cable and position a mat on le sol in front of it. 2. Sit down with vos pieds toward the pulley and attach the cable to your ankles. 3. Lie down, elevate vos jambes and bend your genoux at a 90-degree angle. vos jambes and the cable should be aligned. If not, adjust the pulley up or down until they are. 4. With vos mains behind your head, bring your genoux inward to your torse and elevate your hips off le sol. 5. Pause for a moment and in a slow and controlled manner drop your hips and bring vos jambes back to the starting 90-degree angle. You should still have tension on your abdominaux in the resting position. 6. Repetez the same movement to failure.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Reverse_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rope Overhead Triceps Extension', 'Triceps', 'Poulie', '1. Attach a rope to the bottom pulley of the pulley machine. 2. Grasping the rope with both hands, extend vos bras with vos mains directly above your head using a neutral grip (palms facing each other). Your coudes should be in close to your head and the arms should be perpendicular to le sol with the knuckles aimed at the ceiling. Position de depart. 3. Lentement, lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched. 4. Revenez en position de depart by flexing your triceps as you Expirez. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Overhead_Triceps_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Rope Rear-Delt Rows', 'Épaules', 'Poulie', '1. Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. 2. Attach a rope to the pulley and grasp it with an prise en pronation. vos bras should be extended and parallel to le sol with the coudes flared out. 3. Keep your lower back upright and slide your hips back so that your genoux are slightly bent. Position de depart. 4. Pull the cable attachment towards your upper poitrine, just below the neck, as you keep your coudes up and out to the sides. Continue this motion en expirant until the coudes travel slightly behind the back. Conseil : Keep your upper arms horizontal, perpendicular to the torse and parallel to le sol throughout the motion. 5. Go back to the initial position where the arms are extended and the epaules are stretched forward. Inhale as you perform this portion of le mouvement. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Biceps, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Rope_Rear-Delt_Rows/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Russian Twists', 'Abdominaux', 'Poulie', '1. Connect a standard handle attachment, and position the cable to a middle pulley position. 2. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the poids on the cable. 3. Grab the handle with both hands and fully extend vos bras above your poitrine. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are. 4. Keep your hips elevated and abdominaux engaged. Rotate your torse away from the pulley for a full-quarter rotation. votre corps should be flat from head to genoux. 5. Pause for a moment and in a slow and controlled manner reset to the position de depart. You should still have side tension on the cable in the resting position. 6. Repetez the same movement to failure. 7. Then, reposition and Repetez the same series of movements on the opposite side.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Russian_Twists/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Seated Crunch', 'Abdominaux', 'Poulie', '1. Seat on a flat banc with votre dos facing a high pulley. 2. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place vos mains securely over both epaules. Conseil : Allow the poids to hyperextend the lower back slightly. Position de depart. 3. With the hips stationary, flex the waist so the coudes travel toward the hips. Expirez as you perform this step. 4. en inspirant, go back to the initial position slowly. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Seated Lateral Raise', 'Épaules', 'Poulie', '1. Stand in the middle of two low pulleys that are opposite to each other and place a flat banc right behind you (in perpendicular fashion to you; the narrow edge of the banc should be the one behind you). Select the poids to be used on each pulley. 2. Now sit at the edge of the flat banc behind you with vos pieds placed in front of your genoux. 3. Bend forward while keeping votre dos flat and rest your torse on the cuisses. 4. Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your poids. The pulleys should run under your genoux and vos bras will be extended with palms facing each other and a slight bend at the coudes. This will be the position de depart. 5. While keeping the arms stationary, raise the upper arms to the sides until they are parallel to le sol and at epaules height. Exhale during the execution of this movement and hold the contraction for a second. 6. Lentement, lower vos bras to the position de depart en inspirant. 7. Repetez selon le nombre souhaite. Conseil : Maintain upper arms perpendicular to torse and a fixed coudes position (10 degree to 30 degree angle) throughout exercise.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Seated_Lateral_Raise/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Shoulder Press', 'Épaules', 'Poulie', '1. Move the cables to the bottom of the towers and select an appropriate poids. 2. Stand directly in between the uprights. Grasp the cables and hold them at epaules height, palms facing forward. Position de depart. 3. Keeping your head and poitrine up, extend through the coudes to press the handles directly over head. 4. After pausing at the top, Revenez en position de depart and Repetez.', 'Muscles secondaires : Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shoulder_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Shrugs', 'Trapèzes', 'Poulie', '1. Grasp a cable bar attachment that is attached to a low pulley with a epaules width or slightly wider overhand (palms facing down) grip. 2. Stand erect close to the pulley with vos bras extended in front of you holding the bar. Position de depart. 3. Lift the bar by elevating the epaules as high as possible en expirant. Hold the contraction at the top for a second. Conseil : The arms should remain extended en permanence. Refrain from using the biceps to help lift the bar. Only the epaules should be moving up and down. 4. Lower the bar back to the original position. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Shrugs/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cable Wrist Curl', 'Avant-bras', 'Poulie', '1. Start out by placing a flat banc in front of a low pulley cable that has a straight bar attachment. 2. Use vos bras to grab the cable bar with a narrow to epaules width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your cuisses. Your poignets should be hanging just beyond your genoux. 3. Start out by curling your poignets upwards and exhaling. Keep the contraction for a second. 4. Lentement, lower your poignets back down to the position de depart while inhaling. 5. Your forearms should be stationary as your poignets is the only movement needed to perform this exercise. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Wrist_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf-Machine Shoulder Shrug', 'Trapèzes', 'Machine', '1. Position yourself on the calf machine so that the epaules pads are above your epaules. Your torse should be straight with the arms extended normally by your side. Position de depart. 2. Raise your epaules up towards your ears en expirant and hold the contraction for a full second. 3. Lentement, Revenez en position de depart en inspirant. 4. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf-Machine_Shoulder_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Press', 'Mollets', 'Machine', '1. Adjust the seat so that vos jambes are only slightly bent in the start position. The balls of vos pieds should be firmly on the platform. 2. Select an appropriate poids, and grasp the handles. Position de depart. 3. Straighten the legs by extending the genoux, just barely lifting the poids from the stack. Your ankle should be fully flexed, toes pointing up. Execute le mouvement by pressing downward through the balls of vos pieds as far as possible. 4. Apres une pause, reverse the motion and Repetez.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Press On The Leg Press Machine', 'Mollets', 'Machine', '1. Using a leg press machine, sit down on the machine and place vos jambes on the platform directly in front of you at a medium (epaules width) foot stance. 2. Lower the safety bars holding the weighted platform in place and press the platform all the way up until vos jambes are fully extended in front of you without locking your genoux. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torse and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of vos pieds on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. Position de depart. 3. Press on the platform by raising your heels as you Expirez by extending your ankles as high as possible and flexing your calf. Ensure that the genoux is kept stationary en permanence. There should be no bending at any time. Hold the contracted position by a second before you start to go back down. 4. Go back Lentement, to the position de depart as you Inspirez by lowering your heels as you bend the ankles until mollets are stretched. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Press_On_The_Leg_Press_Machine/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Raise On A Dumbbell', 'Mollets', 'Haltères', '1. Hang on to a sturdy object for balance and stand on a halteres handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. 2. Now roll your foot slightly forward so that you can get a nice stretch of the calf. Position de depart. 3. Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and Maintenez 1 seconde. Conseil : As you come up, roll the halteres slightly backward. 4. Now inhale as you roll the halteres slightly forward as you come down to get a better stretch. 5. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raise_On_A_Dumbbell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Raises - With Bands', 'Mollets', 'Élastique', '1. Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. 2. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a epaules press. The palms should be facing forward with the coudes bent and to the sides. This movement will create tension on the band. Position de depart. 3. Keeping the hands by your epaules, stand up on your toes en expirant and contract the mollets hard at the top of le mouvement. 4. After a one second contraction, Lentement, go back down to the position de depart. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Stretch Elbows Against Wall', 'Mollets', 'Autre', '1. Stand facing a wall from a couple feet away. 2. Lean against the wall, placing your poids on your forearms. 3. Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Elbows_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calf Stretch Hands Against Wall', 'Mollets', 'Autre', '1. Stand facing a wall from several feet away. Stagger your stance, placing one foot forward. 2. Lean forward and rest vos mains on the wall, keeping your heel, hip and head in a straight line. 3. Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Stretch_Hands_Against_Wall/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Calves-SMR', 'Mollets', 'Foam roller', '1. Begin seated on le sol. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on le sol, supporting some of your poids. Position de depart. 2. Place vos mains to your side or just behind you, and press down to raise your hips off of le sol, placing much of your poids against your calf muscle. Roll from below the genoux to above the ankle, pausing at points of tension for 10-30 seconds. Repetez de l autre cote.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calves-SMR/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Car Deadlift', 'Quadriceps', 'Autre', '1. This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs. 2. Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With vos pieds and your grip set, take a big breath and then lower your hips and flex the genoux. 3. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. As the poids comes up, pull your omoplates together as you drive your hips forward. 4. Lower the poids by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Car Drivers', 'Épaules', 'Barre', '1. While standing upright, hold a barre plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and vos bras should be extended straight out in front of you. Position de depart. 2. Initiate le mouvement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. 3. Reverse the motion, turning it all the way to the opposite side. 4. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Carioca Quick Step', 'Adducteurs', 'Autre', '1. Begin with vos pieds a few inches apart and your left arm up in a relaxed, athletic position. 2. With your right foot, quick step behind and pull the genoux up. 3. Fire vos bras back up when you pull the right genoux, being sure that your genoux goes straight up and down. Avoid turning vos pieds as you move and continue to look forward as you move to the side.', 'Muscles secondaires : Abdominaux, Abducteurs, Mollets, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Carioca_Quick_Step/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cat Stretch', 'Bas du dos', 'Autre', '1. Position yourself on le sol on vos mains and genoux. 2. Pull your belly in and round your spine, lower back, epaules, and neck, letting your head drop. 3. Hold for 15 seconds.', 'Muscles secondaires : Milieu du dos, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cat_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Catch and Overhead Throw', 'Dos', 'Medecine ball', '1. Begin standing while facing a wall or a partner. 2. Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. 3. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.', 'Muscles secondaires : Abdominaux, Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Catch_and_Overhead_Throw/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chain Handle Extension', 'Triceps', 'Autre', '1. You will need two cable handle attachments and a flat banc, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat banc. Your coudes should be pointing straight up. 2. Begin by extending through the coudes, keeping your upper arm still, with your poignets pronated. 3. Pause at the lockout, and reverse the motion to Revenez en position de depart.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Handle_Extension/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chain Press', 'Pectoraux', 'Autre', '1. Begin by connecting the chains to the cable handle attachments. Position yourself on the flat banc in the same position as for a halteres press. Your poignets should be pronated and arms perpendicular to le sol. Position de depart. 2. Lower the chains by flexing the coudes, unloading some of the chain onto le sol. 3. Continue until your coudes forms a 90 degree angle, and then reverse the motion by extending through the coudes to lockout.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chain_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Leg Extended Stretch', 'Ischio-jambiers', 'Autre', '1. Sit upright in a chair and grip the seat on the sides. 2. Raise one leg, extending the genoux, flexing the ankle as you do so. 3. Lentement, move that leg outward as far as you can, and then back to the center and down. 4. Repetez for your other leg.', 'Muscles secondaires : Adducteurs. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Leg_Extended_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Lower Back Stretch', 'Dos', 'Autre', '1. Sit upright on a chair. 2. Bend to one side with your arm over your head. You can hold onto the chair with your free hand. 3. Hold for 10 seconds, and Repetez for your other side.', 'Muscles secondaires : Bas du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Lower_Back_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Squat', 'Quadriceps', 'Machine', '1. To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your epaules. 2. Take the bar with vos mains facing forward, unlock it and lift it off the rack by extending vos jambes. 3. Move vos pieds forward about 18 inches in front of the bar. Position vos jambes using a epaules width stance with the toes slightly pointed out. Look forward en permanence and maintain a neutral or slightly arched spine. Position de depart. 4. Lentement, lower the bar by bending the genoux as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees. 5. Begin to raise the bar en expirant by pushing le sol with the heels of vos pieds, extending the genoux and returning to the position de depart. 6. Repetez selon le nombre souhaite.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Squat/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chair Upper Body Stretch', 'Épaules', 'Autre', '1. Sit on the edge of a chair, gripping the back of it. 2. Straighten vos bras, keeping votre dos straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.', 'Muscles secondaires : Biceps, Pectoraux. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chair_Upper_Body_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest And Front Of Shoulder Stretch', 'Pectoraux', 'Autre', '1. Start off by standing with vos jambes together, holding a bodybar or a broomstick. 2. Take a slightly wider than epaules width grip on the pole and hold it in front of you with your palms facing down. 3. Carefully lift the pole up and behind your head.', 'Muscles secondaires : Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_And_Front_Of_Shoulder_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push from 3 point stance', 'Pectoraux', 'Medecine ball', '1. Begin in a three point stance, squatted down with votre dos flat and one hand on the ground. Place the medicine ball directly in front of you. 2. To begin, take your first step as you pull the ball to your poitrine, positioning both hands to prepare for the throw. 3. As you execute the second step, explosively release the ball forward as hard as possible.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_from_3_point_stance/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push (multiple response)', 'Pectoraux', 'Medecine ball', '1. Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the poitrine. 2. Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. 3. Follow through by falling forward, catching yourself with vos mains. 4. Immediately return to an upright position. Repetez for the desired number of repetitions.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_multiple_response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push (single response)', 'Pectoraux', 'Medecine ball', '1. Begin in a kneeling position holding the medicine ball with both hands tightly into the poitrine. 2. Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. 3. Follow through by falling forward, catching yourself with vos mains.', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_single_response/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Push with Run Release', 'Pectoraux', 'Medecine ball', '1. Begin in an athletic stance with the genoux bent, hips back, and back flat. Hold the medicine ball near vos jambes. Position de depart. 2. While taking your first step draw the medicine ball into your poitrine. 3. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!', 'Muscles secondaires : Abdominaux, Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Push_with_Run_Release/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chest Stretch on Stability Ball', 'Pectoraux', 'Swiss ball', '1. Get on vos mains and genoux next to an exercise ball. 2. Place your coudes on top of the ball, keeping your arm out to your side. Position de depart. 3. Lower your torse towards le sol, keeping your coudes on top of the ball. Hold the stretch for 20-30 seconds, and Repetez with the other arm.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chest_Stretch_on_Stability_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Child''s Pose', 'Bas du dos', 'Autre', '1. Get on vos mains and genoux, walk vos mains in front of you. 2. Lower your buttocks down to sit on your heels. Let vos bras drag along le sol as you sit back to stretch your entire spine. 3. Once you settle onto your heels, bring vos mains next to vos pieds and relax. "breathe" into votre dos. Rest your forehead on le sol. Avoid this position if you have genoux problems.', 'Muscles secondaires : Fessiers, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Childs_Pose/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chin-Up', 'Dos', 'Poids de corps', '1. Grab the pull-up bar with the palms facing your torse and a grip closer than the epaules width. 2. As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torse as straight as possible while creating a curvature on your lower back and sticking your poitrine out. Position de depart. Conseil : Keeping the torse as straight as possible maximizes biceps stimulation while minimizing back involvement. 3. As you Expirez, pull your torse up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform le mouvement. Keep the coudes close to votre corps. Conseil : The upper torse should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar. 4. After a second of squeezing the biceps in the contracted position, Lentement, lower your torse back to the position de depart; when vos bras are fully extended. Inspirez as you perform this portion of le mouvement. 5. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Avant-bras, Milieu du dos. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Chin To Chest Stretch', 'Cou', 'Autre', '1. Get into a seated position on le sol. 2. Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and coudes pointing straight ahead. Lentement, pull your head down to your poitrine. Hold for 20-30 seconds.', 'Muscles secondaires : Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Chin_To_Chest_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Circus Bell', 'Épaules', 'Autre', '1. The circus bell is an oversized halteres with a thick handle. Begin with the halteres between vos pieds, and grip the handle with both hands. 2. Clean the halteres by extending through your hips and genoux to deliver the implement to the desired epaules, letting go with the extra hand. 3. Ensure that you get one of the halteres heads behind the epaules to keep from being thrown off balance. To raise it overhead, dip by flexing the genoux, and the drive upwards as you extend the halteres overhead, leaning slightly away from it as you do so. 4. Carefully guide the bell back to le sol, keeping it under control as much as possible. It is best to perform this event on a thick rubber mat to prevent damage to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Circus_Bell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean', 'Ischio-jambiers', 'Barre', '1. With a barre on le sol close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2.  3. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 4. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 5. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 6. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position.', 'Muscles secondaires : Mollets, Avant-bras, Fessiers, Bas du dos, Quadriceps, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Deadlift', 'Ischio-jambiers', 'Barre', '1. Begin standing with a barre close to your shins. vos pieds should be directly under your hips with vos pieds turned out slightly. Grip the bar with a double prise en pronation or hook grip, about epaules width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your epaules in front of the bar and votre dos as vertical as possible. 2. Begin by driving through le sol through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your genoux out to the side to help keep them out of the bar''s path. 3. After the bar crosses the genoux, complete the lift by driving the hips into the bar until your hips and genoux are extended.', 'Muscles secondaires : Avant-bras, Fessiers, Bas du dos, Milieu du dos, Quadriceps, Trapèzes. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Deadlift/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Pull', 'Quadriceps', 'Barre', '1. With a barre on le sol close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight and coudes out. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. Full extension should be violent and abrupt, and ensure that you do not prolong the extension for longer than necessary.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Bas du dos, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Pull/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean Shrug', 'Trapèzes', 'Barre', '1. Begin with a epaules width, double overhand or hook grip, with the bar hanging at the mid cuisses position. votre dos should be straight and inclined slightly forward. 2. Shrug your epaules towards your ears. While this exercise can usually by loaded with heavier poids than a clean, avoid overloading to the point that the execution slows down.', 'Muscles secondaires : Avant-bras, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_Shrug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean and Jerk', 'Épaules', 'Barre', '1. With a barre on le sol close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight. Move the poids with control as you continue to above the genoux. 3. Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-cuisses position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, genoux, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the poids; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended. 4. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the coudes up and out. At peak extension, aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 5. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position. 6. The second phase is the jerk, which raises the poids overhead. Standing with the poids racked on the front of the epaules, begin with the dip. With vos pieds directly under your hips, flex the genoux without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. 7. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the epaules. 8. At this moment as the feet leave le sol, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.', 'Muscles secondaires : Abdominaux, Fessiers, Ischio-jambiers, Bas du dos, Quadriceps, Trapèzes, Triceps. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Jerk/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean and Press', 'Épaules', 'Barre', '1. Assume a epaules-width stance, with genoux inside the arms. Now while keeping the back flat, bend at the genoux and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than epaules width. Point the coudes out to sides. The bar should be close to the shins. Position the epaules over or slightly ahead of the bar. Establish a flat back posture. Position de depart. 2. Begin to pull the bar by extending the genoux. Move your hips forward and raise the epaules at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to votre corps. 3. As the bar passes the genoux, extend at the ankles, genoux, and hips forcefully, similar to a jumping motion. As you do so, continue to guide the bar with vos mains, shrugging your epaules and using the momentum from your movement to pull the bar as high as possible. The bar should travel close to votre corps, and you should keep your coudes out. 4. At maximum elevation, vos pieds should clear le sol and you should start to pull yourself under the bar. The mechanics of this could change slightly, depending on the poids used. You should descend into a squatting position as you pull yourself under the bar. 5. As the bar hits terminal height, rotate your coudes around and under the bar. Rack the bar across the front of the epaules while keeping the torse erect and flexing the hips and genoux to absorb the poids of the bar. 6. Stand to full height, holding the bar in the clean position. 7. Without moving vos pieds, press the bar overhead en expirant. Lower the bar under control .', 'Muscles secondaires : Abdominaux, Mollets, Fessiers, Ischio-jambiers, Bas du dos, Milieu du dos, Quadriceps, Épaules, Trapèzes, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_and_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clean from Blocks', 'Quadriceps', 'Barre', '1. With a barre on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the poids focused on the heels, back straight, head facing forward, poitrine up, with your epaules just in front of the bar. Position de depart. 2. Begin the first pull by driving through the heels, extending your genoux. votre dos angle should stay the same, and vos bras should remain straight with the coudes pointed out. 3. As full extension is achieved, transition into the receiving position by aggressively shrugging and flexing the arms with the coudes up and out. Aggressively pull yourself down, rotating your coudes under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted epaules, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery. 4. Immediately recover by driving through the heels, keeping the torse upright and coudes up. Continue until you have risen to a standing position. Return the poids to the boxes for the next rep.', 'Muscles secondaires : Mollets, Fessiers, Ischio-jambiers, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clean_from_Blocks/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Clock Push-Up', 'Pectoraux', 'Poids de corps', '1. Move into a prone position on le sol, supporting your poids on vos mains and toes. 2. vos bras should be fully extended with the hands around epaules width. Keep votre corps straight throughout le mouvement. Position de depart. 3. Descend by flexing at the coudes, lowering your poitrine toward the ground. 4. At the bottom, reverse the motion by pushing yourself up through coudes extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side. 5. As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift votre corps about 30 degrees for the next repetition. 6. Revenez en position de depart and Repetez the exercise, working all the way around until you are back where you started.', 'Muscles secondaires : Épaules, Triceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Clock_Push-Up/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Barbell Bench Press', 'Triceps', 'Barre', '1. Allongez-vous au sol on a flat banc. Using a close grip (around epaules width), lift the bar from the rack and hold it straight over you with vos bras locked. Position de depart. 2. As you Inspirez, come down Lentement, until you feel the bar on your middle poitrine. Conseil : Make sure that - as opposed to a regular banc press - you keep the coudes close to the torse en permanence in order to maximize triceps involvement. 3. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your triceps muscles. Lock vos bras in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up. 4. Repetez le mouvement for the prescribed amount of repetitions. 5. When you are done, place the bar back in the rack.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Dumbbell Press', 'Triceps', 'Haltères', '1. Place a halteres standing up on a flat banc. 2. Ensuring that the halteres stays securely placed at the top of the banc, lie perpendicular to the banc with only your epaules lying on the surface. Hips should be below the banc and vos jambes bent with vos pieds firmly on le sol. 3. Grasp the halteres with both hands and hold it straight over your poitrine at arm''s length. Both palms should be pressing against the underside of the sides of the halteres. Position de depart. 4. Initiate le mouvement by lowering the halteres to your poitrine. 5. Revenez en position de depart by extending the coudes.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Dumbbell_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ-Bar Curl with Band', 'Biceps', 'Barre EZ', '1. Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The coudes should be close to the torse. Position de depart. 2. While keeping the upper arms in place, flex the coudes to execute the curl. Exhale as the poids is lifted. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ-Bar Press', 'Triceps', 'Barre EZ', '1. Allongez-vous sur un banc plat with an EZ bar loaded to an appropriate poids. 2. Using a prise serree lift the bar and hold it straight over your torse with your coudes in. The arms should be perpendicular to le sol. Position de depart. 3. Now lower the bar down to your lower poitrine as you Inspirez. Keep the coudes in as you perform this movement. 4. Using the triceps to push the bar back up, press it back to the position de depart by extending the coudes en expirant. 5. Repetez.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip EZ Bar Curl', 'Biceps', 'Barre', '1. Tenez-vous debout avec your torse upright while holding an E-Z Curl Bar at the closer inner handle. The palm of vos mains should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The coudes should be close to the torse. Position de depart. 2. While holding the upper arms stationary, curl the poids forward while contracting the biceps as you Expirez. Conseil : Only the forearms should move. 3. Continue le mouvement until your biceps are entierement contracte and the bar is at epaules level. Maintenez 1 seconde and squeeze the biceps hard. 4. Lentement, begin to bring the bar back to position de depart as your Inspirez. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Front Lat Pulldown', 'Dos', 'Poulie', '1. Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the genoux pad of the machine to fit your height. These pads will prevent votre corps from being raised by the resistance attached to the bar. 2. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a prise large, vos mains need to be spaced out at a distance wider than your epaules width. For a prise moyenne, vos mains need to be spaced out at a distance equal to your epaules width and for a close grip at a distance smaller than your epaules width. 3. As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torse back around 30 degrees or so while creating a curvature on your lower back and sticking your poitrine out. Position de depart. 4. As you Expirez, bring the bar down until it touches your upper poitrine by drawing the epaules and the upper arms down and back. Conseil : Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torse should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms. 5. After a second in the contracted position, while squeezing your omoplates together, Lentement, raise the bar back to the position de depart when vos bras are fully extended and the lats are fully stretched. Inhale during this portion of le mouvement. 6. 6. Repetez this motion for the prescribed amount of repetitions.', 'Muscles secondaires : Biceps, Milieu du dos, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Push-Up off of a Dumbbell', 'Triceps', 'Poids de corps', '1. Allongez-vous au sol and place vos mains on an upright halteres. Supporting your poids on your toes and hands, keep your torse rigid and your coudes in with vos bras straight. Position de depart. 2. Lower votre corps, allowing the coudes to flex while you inhale. Keep votre corps straight, not allowing your hips to rise or sag. 3. Press yourself back up to the position de depart by extending the coudes. Expirez as you perform this step. 4. Apres une pause, at the contracted position, Repetez le mouvement for the prescribed amount of repetitions.', 'Muscles secondaires : Abdominaux, Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Close-Grip Standing Barbell Curl', 'Biceps', 'Barre', '1. Hold a barre with both hands, palms up and a few inches apart. 2. Tenez-vous debout avec your torse straight and your head up. vos pieds should be about epaules width and your coudes close to your torse. Position de depart. Conseil : You will keep your upper arms and coudes stationary throughout le mouvement. 3. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of le mouvement and contract your biceps hard for a second at the top. Conseil : Avoid bending the back or using swinging motions as you lift the poids. Only the forearms should move. 4. Lentement, go back down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cocoons', 'Abdominaux', 'Poids de corps', '1. Begin by lying on votre dos on the ground. vos jambes should be straight and vos bras extended behind your head. Position de depart. 2. To perform le mouvement, tuck the genoux toward your poitrine, rotating your pelvis to lift your fessiers from le sol. As you do so, flex the spine, bringing vos bras back over your head to perform a simultaneous crunch motion. 3. Apres une pause, Revenez en position de depart.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cocoons/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Conan''s Wheel', 'Quadriceps', 'Autre', '1. With the poids loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the coudes and hold onto your poignets. Try to keep the poids off of the forearms. 2. Begin by lifting the poids from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.', 'Muscles secondaires : Abdominaux, Biceps, Mollets, Avant-bras, Bas du dos, Épaules, Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Conans_Wheel/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Concentration Curls', 'Biceps', 'Haltères', '1. Sit down on a flat banc with one halteres in front of you between vos jambes. vos jambes should be spread with your genoux bent and feet on le sol. 2. Use your right arm to pick the halteres up. Place the back of your right upper arm on the top of your inner right cuisses. Rotate the palm of your hand until it is facing forward away from your cuisses. Conseil : Your arm should be extended and the halteres should be above le sol. Position de depart. 3. While holding the upper arm stationary, curl the poids forward while contracting the biceps as you Expirez. Only the forearms should move. Continue le mouvement until your biceps are entierement contracte and the halteres are at epaules level. Conseil : At the top of le mouvement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Maintenez 1 seconde as you squeeze the biceps. 4. Lentement, begin to bring the halteres back to position de depart as your Inspirez. Caution: Avoid swinging motions at any time. 5. Repetez selon le nombre souhaite. Then Repetez le mouvement with the left arm.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Concentration_Curls/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross-Body Crunch', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol and bend your genoux about 60 degrees. 2. Keep vos pieds flat on le sol and place vos mains loosely behind your head. Position de depart. 3. Now curl up and bring your right coudes and epaules across votre corps while bring your left genoux in toward your left epaules at the same time. Reach with your coudes and try to touch your genoux. Exhale as you perform this movement. Conseil : Try to bring your epaules up towards your genoux rather than just your coudes and remember that the key is to contract the abdominaux as you perform le mouvement; not just to move the coudes. 4. Now go back down to the position de depart en inspirant and Repetez with the left coudes and the right genoux. 5. Continue alternating in this manner until all prescribed repetitions are done.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross-Body_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross Body Hammer Curl', 'Biceps', 'Haltères', '1. Tenez-vous debout avec a halteres in each hand. vos mains should be down at your side with your palms facing in. 2. While keeping your palms facing in and without twisting your arm, curl the halteres of the right arm up towards your left epaules en expirant. Touch the top of the halteres to your epaules and hold the contraction for a second. 3. Lentement, lower the halteres along the same path en inspirant and then Repetez the same movement for the left arm. 4. Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Body_Hammer_Curl/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cross Over - With Bands', 'Pectoraux', 'Élastique', '1. Secure an exercise band around a stationary post. 2. While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. 3. Raise vos bras to the sides, parallel to le sol, perpendicular to your torse (your torse and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the coudes. Position de depart. 4. While keeping vos bras straight, bring them across your poitrine in a semicircular motion to the front en expirant and flex your pecs. Hold the contraction for a second. 5. Lentement, Revenez en position de depart en inspirant. 6. Perform for the recommended amount of repetitions.', 'Muscles secondaires : Biceps, Épaules. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cross_Over_-_With_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crossover Reverse Lunge', 'Bas du dos', 'Autre', '1. Tenez-vous debout avec vos pieds epaules width apart. Position de depart. 2. Perform a rear lunge by stepping back with one foot and flexing the hips and front genoux. As you do so, rotate your torse across the front leg. 3. Apres une pause, Revenez en position de depart and Repetez de l autre cote, continuing in an alternating fashion.', 'Muscles secondaires : Abdominaux, Abducteurs, Fessiers, Ischio-jambiers, Quadriceps. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crossover_Reverse_Lunge/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crucifix', 'Épaules', 'Autre', '1. In the crucifix, you statically hold poids out to the side for time. While the event can be practiced using halteres, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different. 2. Begin standing, and raise vos bras out to the side holding the implements. vos bras should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the poids should be heavy enough that you fail in 30-60 seconds.', 'Muscles secondaires : Avant-bras. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crucifix/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunch - Hands Overhead', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with votre dos flat and genoux bent with around a 60-degree angle between the ischio-jambiers and the mollets. 2. Keep vos pieds flat on le sol and stretch vos bras overhead with your palms crossed. Position de depart. 3. Curl your upper body forward and bring your omoplates just off le sol. en permanence, keep vos bras aligned with your head, neck and epaules. Don''t move them forward from that position. Exhale as you perform this portion of le mouvement and hold the contraction for a second. 4. Lentement, lower down to the position de depart en inspirant. 5. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Hands_Overhead/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunch - Legs On Exercise Ball', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos pieds resting on an exercise ball and your genoux bent at a 90 degree angle. 2. Place vos pieds three to four inches apart and point your toes inward so they touch. 3. Place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 4. Push the small of votre dos down in le sol in order to better isolate your abdominal muscles. Position de depart. 5. Begin to roll your epaules off le sol and continue to push down as hard as you can with your lower back. Your epaules should come up off le sol only about four inches, and your lower back should remain on le sol. Expirez as you execute this portion of le mouvement. Squeeze your abdominals hard at the top of the contraction and Maintenez 1 seconde. Conseil : Focus on a slow, controlled movement. Refrain from using momentum at any time. 6. Lentement, go back down to the position de depart en inspirant. 7. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Crunches', 'Abdominaux', 'Poids de corps', '1. Allongez-vous au sol with vos pieds flat on the ground, or resting on a banc with your genoux bent at a 90 degree angle. If you are resting vos pieds on a banc, place them three to four inches apart and point your toes inward so they touch. 2. Now place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 3. While pushing the small of votre dos down in le sol to better isolate your abdominal muscles, begin to roll your epaules off le sol. 4. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your epaules should come up off le sol only about four inches, and your lower back should remain on le sol. At the top of le mouvement, contract your abdominals hard and keep the contraction for a second. Conseil : Focus on slow, controlled movement - don''t cheat yourself by using momentum. 5. After the one second contraction, begin to come down Lentement, again to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunches/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Cuban Press', 'Épaules', 'Haltères', '1. Take a halteres in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to le sol, allowing your lower arms to hang in the "scarecrow" position. Position de depart. 2. To initiate le mouvement, externally rotate the epaules to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the poignets are directly above the coudes, the forearms perpendicular to le sol. 3. Now press the halteres by extending at the coudes, straightening vos bras overhead. 4. Revenez en position de depart as you Inspirez by reversing the steps. 5. Repetez selon le nombre souhaite.', 'Muscles secondaires : Trapèzes. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cuban_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dancer''s Stretch', 'Bas du dos', 'Autre', '1. Sit up on le sol. 2. Cross your right leg over your left, keeping the genoux bent. Your left leg is straight and down on le sol. 3. Place your left arm on your right leg and your right hand on le sol. 4. Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.', 'Muscles secondaires : Abducteurs, Fessiers. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dancers_Stretch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Dead Bug', 'Abdominaux', 'Poids de corps', '1. Begin lying on votre dos with vos mains extended above you toward the ceiling. 2. Bring vos pieds, genoux, and hips up to 90 degrees. 3. Exhale hard to bring your ribcage down and flatten votre dos onto le sol, rotating your pelvis up and squeezing your fessiers. Hold this position throughout le mouvement. Position de depart. 4. Initiate the exercise by extending one leg, straightening the genoux and hip to bring the leg just above the ground. 5. Maintain the position of your lumbar and pelvis as you perform le mouvement, as votre dos is going to want to arch. 6. Stay tight and return the working leg to the position de depart. 7. Repetez de l autre cote, alternating until the set is complete.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dead_Bug/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Deadlift with Bands', 'Bas du dos', 'Barre', '1. To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy halteres or a rack. 2. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 3. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Bands/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Deadlift with Chains', 'Bas du dos', 'Barre', '1. You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater poids increase as you lift. 2. Approach the bar so that it is centered over vos pieds. You feet should be about hip width apart. Bend at the hip to grip the bar at epaules width, allowing your omoplates to protract. Typically, you would use an prise en pronation or an over/under grip on heavier sets. With vos pieds, and your grip set, take a big breath and then lower your hips and bend the genoux until your shins contact the bar. 3. Look forward with your head, keep your poitrine up and votre dos arched, and begin driving through the heels to move the poids upward. After the bar passes the genoux, aggressively pull the bar back, pulling your omoplates together as you drive your hips forward into the bar. 4. Lower the bar by bending at the hips and guiding it to le sol.', 'Muscles secondaires : Avant-bras, Fessiers, Ischio-jambiers, Milieu du dos, Quadriceps, Trapèzes. Niveau : Avance.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Chains/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Barbell Bench Press', 'Pectoraux', 'Barre', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Using a prise moyenne (a grip that creates a 90-degree angle in the middle of le mouvement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with vos bras locked. The arms should be perpendicular to le sol. Position de depart. Conseil : In order to protect your rotator cuff, it is best if you have a spotter help you lift the barre off the rack. 3. As you Inspirez, come down Lentement, until you feel the bar on your lower poitrine. 4. Apres une pause, bring the bar back to the position de depart as you Expirez and push the bar using your poitrine muscles. Lock vos bras and squeeze your poitrine in the contracted position, Maintenez 1 seconde and then start coming down Lentement, again. Conseil : It should take at least twice as long to go down than to come up). 5. Repetez le mouvement for the prescribed amount of repetitions. 6. When you are done, place the bar back in the rack.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Barbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Close-Grip Bench To Skull Crusher', 'Triceps', 'Barre', '1. Secure vos jambes at the end of the decline banc and Lentement, lay down on the banc. 2. Using a close grip (a grip that is slightly less than epaules width), lift the bar from the rack and hold it straight over you with vos bras locked and coudes in. The arms should be perpendicular to le sol. Position de depart. Conseil : In order to protect your rotator cuff, it is best if you have a spotter help you lift the barre off the rack. 3. Now lower the bar down to your lower poitrine as you Inspirez. Keep the coudes in as you perform this movement. 4. Using the triceps to push the bar back up, press it back to the position de depart en expirant. 5. As you Inspirez and you keep the upper arms stationary, bring the bar down Lentement, by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Inspirez as you perform this portion of le mouvement. 6. Lift the bar back to the position de depart by contracting the triceps and exhaling. 7. Repetez steps 3-6 until the recommended amount of repetitions is performed.', 'Muscles secondaires : Pectoraux, Épaules. Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Crunch', 'Abdominaux', 'Poids de corps', '1. Secure vos jambes at the end of the decline banc and lie down. 2. Now place vos mains lightly on either side of your head keeping your coudes in. Conseil : Don''t lock your fingers behind your head. 3. While pushing the small of votre dos down in the banc to better isolate your abdominal muscles, begin to roll your epaules off it. 4. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your epaules should come up off the banc only about four inches, and your lower back should remain on the banc. At the top of le mouvement, contract your abdominals hard and keep the contraction for a second. Conseil : Focus on slow, controlled movement - don''t cheat yourself by using momentum. 5. After the one second contraction, begin to come down Lentement, again to the position de depart en inspirant. 6. Repetez selon le nombre souhaite.', 'Niveau : Intermediaire.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Crunch/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Dumbbell Bench Press', 'Pectoraux', 'Haltères', '1. Secure vos jambes at the end of the decline banc and lie down with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. Once you are laying down, move the halteres in front of you at epaules width. 3. Once at epaules width, rotate your poignets forward so that the palms of vos mains are facing away from you. Position de depart. 4. Bring down the poids Lentement, to your side as you Expirez. Keep full control of the halteres en permanence. Conseil : Throughout the motion, the forearms should always be perpendicular to le sol. 5. As you Expirez, push the halteres up using your pectoral muscles. Lock vos bras in the contracted position, squeeze your poitrine, Maintenez 1 seconde and then start coming down slowly. Conseil : It should take at least twice as long to go down than to come up.. 6. Repetez le mouvement for the prescribed amount of repetitions of your training program.', 'Muscles secondaires : Épaules, Triceps. Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Bench_Press/0.jpg') ON CONFLICT DO NOTHING;
INSERT INTO public.exercises (name, muscle_group, equipment, description, tips, gif_url) VALUES ('Decline Dumbbell Flyes', 'Pectoraux', 'Haltères', '1. Secure vos jambes at the end of the decline banc and lie down with a halteres on each hand on top of your cuisses. The palms of your hand will be facing each other. 2. Once you are laying down, move the halteres in front of you at epaules width. The palms of the hands should be facing each other and the arms should be perpendicular to le sol and fully extended. Position de depart. 3. With a slight bend on your coudes in order to prevent stress at the biceps tendon, lower vos bras out at both sides in a wide arc until you feel a stretch on your poitrine. Inspirez as you perform this portion of le mouvement. Conseil : Keep in mind that throughout le mouvement, the arms should remain stationary; le mouvement should only occur at the epaules joint. 4. Return vos bras back to the position de depart as you squeeze your poitrine muscles and Expirez. Conseil : Make sure to use the same arc of motion used to lower the poids. 5. Maintenez 1 seconde at the contracted position and Repetez le mouvement for the prescribed amount of repetitions.', 'Niveau : Debutant.', 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Flyes/0.jpg') ON CONFLICT DO NOTHING;
